const getEntityHealthCheck = `-- name: GetEntityHealthCheck :one
SELECT
  (
    SELECT
      COUNT(*)
    FROM
      entities
    WHERE
      tenant_id = current_tenant_id()
      AND deleted_at IS NULL
  ) AS active_entities,
  (
    SELECT
      COUNT(*)
    FROM
      hierarchy_paths
    WHERE
      tenant_id = current_tenant_id()
  ) AS hierarchy_paths,
  (
    SELECT
      COUNT(*)
    FROM
      entitystate es
      JOIN entities e ON es.entity_id = e.uuid
    WHERE
      e.tenant_id = current_tenant_id()
  ) AS entity_states,
  (
    SELECT
      COUNT(*)
    FROM
      entities e
      LEFT JOIN entities p ON e.parent_id = p.uuid
    WHERE
      e.tenant_id = current_tenant_id()
      AND e.parent_id IS NOT NULL
      AND p.uuid IS NULL
  ) AS orphaned_entities,
  (
    SELECT
      COUNT(*)
    FROM
      hierarchy_paths hp
      LEFT JOIN entities e1 ON hp.ancestor_id = e1.uuid
      LEFT JOIN entities e2 ON hp.descendant_id = e2.uuid
    WHERE
      hp.tenant_id = current_tenant_id()
      AND (
        e1.uuid IS NULL
        OR e2.uuid IS NULL
      )
  ) AS orphaned_paths
`

type GetEntityHealthCheckRow struct {
	ActiveEntities   int64 `json:"active_entities"`
	HierarchyPaths   int64 `json:"hierarchy_paths"`
	EntityStates     int64 `json:"entity_states"`
	OrphanedEntities int64 `json:"orphaned_entities"`
	OrphanedPaths    int64 `json:"orphaned_paths"`
}

func (q *Queries) GetEntityHealthCheck(ctx context.Context) (*GetEntityHealthCheckRow, error) {
	row := q.db.QueryRow(ctx, getEntityHealthCheck)
	var i GetEntityHealthCheckRow
	err := row.Scan(
		&i.ActiveEntities,
		&i.HierarchyPaths,
		&i.EntityStates,
		&i.OrphanedEntities,
		&i.OrphanedPaths,
	)
	return &i, err
}

