const moveEntityToNewParent = `-- name: MoveEntityToNewParent :exec
WITH RECURSIVE affected_entities AS (
  SELECT
    $1::UUID AS entity_id,
    0 AS depth
  UNION
  ALL
  SELECT
    hp.descendant_id,
    ae.depth + 1
  FROM
    affected_entities ae
    JOIN hierarchy_paths hp ON hp.ancestor_id = ae.entity_id
  WHERE
    ae.depth < 10
),
delete_paths AS (
  DELETE FROM
    hierarchy_paths
  WHERE
    descendant_id IN (
      SELECT
        entity_id
      FROM
        affected_entities
    )
),
insert_new_paths AS (
  INSERT INTO
    hierarchy_paths (tenant_id, ancestor_id, descendant_id, depth)
  SELECT
    current_tenant_id(),
    ancestor_paths.ancestor_id,
    ae.entity_id,
    ancestor_paths.depth + descendant_paths.depth + 1
  FROM
    affected_entities ae
    CROSS JOIN (
      SELECT
        ancestor_id,
        depth
      FROM
        hierarchy_paths
      WHERE
        descendant_id = $2
      UNION
      ALL
      SELECT
        $2::UUID,
        0
    ) ancestor_paths
    CROSS JOIN (
      SELECT
        descendant_id,
        depth
      FROM
        hierarchy_paths
      WHERE
        ancestor_id = $1
      UNION
      ALL
      SELECT
        $1::UUID,
        0
    ) descendant_paths
  WHERE
    ae.entity_id = descendant_paths.descendant_id
)
UPDATE
  entities
SET
  parent_id = $2,
  updated_at = NOW()
WHERE
  uuid = $1
`

type MoveEntityToNewParentParams struct {
	Uuid     uuid.UUID  `json:"uuid"`
	ParentID *uuid.UUID `json:"parent_id"`
}

// =====================================================================
// 3. HIERARCHY BULK OPERATIONS
// =====================================================================
func (q *Queries) MoveEntityToNewParent(ctx context.Context, arg MoveEntityToNewParentParams) error {
	_, err := q.db.Exec(ctx, moveEntityToNewParent, arg.Uuid, arg.ParentID)
	return err
}

const rebuildHierarchyPaths = `-- name: RebuildHierarchyPaths :exec
WITH RECURSIVE entity_hierarchy AS (
  SELECT
    uuid AS ancestor_id,
    uuid AS descendant_id,
    0 AS depth,
    tenant_id
  FROM
    entities
  WHERE
    tenant_id = current_tenant_id()
    AND deleted_at IS NULL
  UNION
  ALL
  SELECT
    eh.ancestor_id,
    e.uuid,
    eh.depth + 1,
    e.tenant_id
  FROM
    entity_hierarchy eh
    JOIN entities e ON e.parent_id = eh.descendant_id
  WHERE
    e.tenant_id = current_tenant_id()
    AND e.deleted_at IS NULL
    AND eh.depth < 10
),
cleanup AS (
  DELETE FROM
    hierarchy_paths
  WHERE
    tenant_id = current_tenant_id()
)
INSERT INTO
  hierarchy_paths (tenant_id, ancestor_id, descendant_id, depth)
SELECT
  tenant_id,
  ancestor_id,
  descendant_id,
  depth
FROM
  entity_hierarchy
`

func (q *Queries) RebuildHierarchyPaths(ctx context.Context) error {
	_, err := q.db.Exec(ctx, rebuildHierarchyPaths)
	return err
}

